                removed.append(p.name)
            except Exception:
                pass

    return {
        "affected_rows": 0,
        "affected_columns": [],
        "affected_files": removed,
        "files_before": len(images),
        "files_after": len(images) - len(removed),
        "warnings": [],
    }

